function metrics(yTrue, yPred) {
  let tp = 0, fp = 0, fn = 0;
  for (let i = 0; i < yTrue.length; i++) {
    if (yPred[i] === 1 && yTrue[i] === 1) tp++;
    else if (yPred[i] === 1) fp++;
    else if (yTrue[i] === 1) fn++;
  }
  const prec = tp + fp ? tp / (tp + fp) : 0;
  const rec = tp + fn ? tp / (tp + fn) : 0;
  return { precision: prec, recall: rec, f1: prec + rec ? (2 * prec * rec) / (prec + rec) : 0 };
}
const yTrue = [0, 0, 1, 1, 0, 1, 0, 1];
const dummy = [0, 0, 0, 0, 0, 0, 0, 0];
const model = [0, 0, 1, 0, 0, 1, 0, 1];
const d = metrics(yTrue, dummy);
const m = metrics(yTrue, model);
console.log('dummy P/R/F1: ' + [d.precision, d.recall, d.f1].map((v) => Math.round(v * 100) / 100).join('/'));
console.log('model P/R/F1: ' + [m.precision, m.recall, m.f1].map((v) => Math.round(v * 100) / 100).join('/'));
console.log('model beats dummy on recall: ' + (m.recall > d.recall));

